values.content:
=Meeting: {{$json.meeting_title}}
Attendees: {{$json.attendees}}
Preferred tone for the email: {{$json.tone}}

NOTES:
{{$json.raw_notes}}

Return JSON with exactly these keys:
{
  "summary": "2-3 sentences on what the meeting was about and where it landed",
  "decisions": ["each decision that was actually made"],
  "action_items": [{"action": "the task", "owner": "who owns it", "due": "when it is due"}],
  "follow_up_email": "a short ready-to-send email in the preferred tone (include a subject line, a 1-line recap, the action items and a friendly sign-off)"
}

Rules: only include real commitments found in the notes. Use "not stated" for any missing owner or due date. Do not wrap the JSON in code fences.

parameters.jsCode:
// Robustly parse the OpenAI reply into a structured meeting debrief.
const raw = $input.first().json.message?.content ?? '';
const cleaned = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let debrief;
try {
  debrief = JSON.parse(cleaned);
} catch (e) {
  // Fallback: keep the prose so the workflow still returns something useful.
  debrief = { summary: cleaned, decisions: [], action_items: [], follow_up_email: '' };
}

const decisions = Array.isArray(debrief.decisions) ? debrief.decisions : [];
const actionItems = Array.isArray(debrief.action_items) ? debrief.action_items : [];

const tableRows = actionItems.map(i =>
  `| ${i.action ?? i.task ?? 'not stated'} | ${i.owner ?? 'not stated'} | ${i.due ?? 'not stated'} |`
);

const debrief_markdown = [
  '## Summary',
  debrief.summary || 'not stated',
  '',
  '## Decisions',
  decisions.length ? decisions.map(d => `- ${d}`).join('\n') : '- not stated',
  '',
  '## Action items',
  actionItems.length
    ? ['| Action | Owner | Due |', '| --- | --- | --- |', ...tableRows].join('\n')
    : '- none identified',
].join('\n');

return [{
  json: {
    meeting_title: $('Set Meeting Notes and Attendees').first().json.meeting_title,
    debrief_markdown,
    follow_up_email: debrief.follow_up_email || 'not stated',
    action_item_count: actionItems.length,
    decisions_count: decisions.length,
  },
}];
